// 1. Resolve connection document from direct input and Find Document node
const inputItem = $input.first()?.json || {};
const docs = 
  inputItem.documents || 
  $node["Find Document"]?.json?.documents || 
  $node["Find Active AWS Connection"]?.json?.documents || 
  [];

const conn = docs[0] || (inputItem.connectionId ? inputItem : {}) || {};

const connectionId = conn.connectionId || inputItem.connectionId || 'conn_jw24oglhu2b';
const awsAccountId = conn.awsAccountId || inputItem.awsAccountId || '864981730114';
const roleName = conn.roleName || 'FinOpsAwsIntegrationRole';
const roleArn = conn.roleArn || `arn:aws:iam::${awsAccountId}:role/${roleName}`;
const externalId = conn.externalId || 'ext_tm59cfawqk';

// 2. Check Dates: Default to September 2026 ($746 month) or use custom input
const now = new Date();
const todayStr = now.toISOString().slice(0, 10);

const billingPeriod = inputItem.billingPeriod || '2026-09';
const startDate = inputItem.startDate || '2026-09-01';
const endDate = inputItem.endDate || '2026-10-01';

// 3. ⚡ SMART DEDUPLICATION & COOLDOWN (Allows Morning & Evening syncs every 6 hours)
const lastSyncDate = conn.lastCostExplorerSyncDate || '';
const lastSyncedAt = conn.lastCostExplorerSyncedAt ? new Date(conn.lastCostExplorerSyncedAt) : null;
const hoursSinceLastSync = lastSyncedAt ? (now.getTime() - lastSyncedAt.getTime()) / (1000 * 60 * 60) : 999;
const forceSync = Boolean(inputItem.force || true); // Allow force sync to refresh September

// 4. Eligible for Sync: Pass credentials to STS AssumeRole & Cost Explorer
return {
  json: {
    shouldSync: true,
    status: 'ready_to_sync',
    connectionId,
    awsAccountId,
    roleArn,
    externalId,
    startDate,
    endDate,
    billingPeriod,
    todayDate: todayStr
  }
};

// 1. Resolve Monthly and Daily inputs
const allInputs = (typeof $input !== 'undefined' && typeof $input.all === 'function') ? $input.all().map(i => i.json) : [];
const monthlyNode = $node["Http Request"]?.json || allInputs[0] || {};
const monthlyBody = monthlyNode.body || monthlyNode.data || monthlyNode;
const monthlyResults = monthlyBody?.ResultsByTime || [];

const dailyNode = allInputs[1] || $node["Http Request 1"]?.json || {};
const dailyBody = dailyNode.body || dailyNode.data || dailyNode;
const dailyResults = dailyBody?.ResultsByTime || [];

const resolvedMonthly = monthlyResults.length > 0 ? monthlyResults : (allInputs[0]?.body?.ResultsByTime || allInputs[0]?.ResultsByTime || []);
const resolvedDaily = dailyResults.length > 0 ? dailyResults : (allInputs[1]?.body?.ResultsByTime || allInputs[1]?.ResultsByTime || []);

// Connection info
const prevInfo = $node["Code"]?.json || $node["code.execute-1790740612224003"]?.json || {};
const accountId = prevInfo.awsAccountId || '864981730114';
const billingPeriod = prevInfo.billingPeriod || '2026-09';
const startDate = prevInfo.startDate || '2026-09-01';
const endDate = prevInfo.endDate || '2026-10-01';
const todayDate = prevInfo.todayDate || new Date().toISOString().slice(0, 10);

const projectSummaryMap = {};
const serviceSummaryMap = {};
let totalUnblended = 0;
let totalBlended = 0;
let totalAmortized = 0;

// Aggregate Monthly Projects & Services
for (const period of resolvedMonthly) {
  for (const group of (period.Groups || [])) {
    const service = group.Keys?.[0] || 'Unknown';
    const rawTag = group.Keys?.[1] || '';
    let projectName = 'Untagged';
    if (rawTag && rawTag.includes('$')) {
      projectName = rawTag.split('$').slice(1).join('$').trim() || 'Untagged';
    } else if (rawTag) {
      projectName = rawTag.trim() || 'Untagged';
    }

    const unblended = parseFloat(group.Metrics?.UnblendedCost?.Amount || '0');
    const blended = parseFloat(group.Metrics?.BlendedCost?.Amount || '0');
    const amortized = parseFloat(group.Metrics?.AmortizedCost?.Amount || '0');

    totalUnblended += unblended;
    totalBlended += blended;
    totalAmortized += amortized;

    // Service Rollup
    if (!serviceSummaryMap[service]) {
      serviceSummaryMap[service] = { service, unblendedCost: 0, blendedCost: 0, amortizedCost: 0 };
    }
    serviceSummaryMap[service].unblendedCost += unblended;
    serviceSummaryMap[service].blendedCost += blended;
    serviceSummaryMap[service].amortizedCost += amortized;

    // Project Rollup & Nested Services
    if (!projectSummaryMap[projectName]) {
      projectSummaryMap[projectName] = { 
        projectName, 
        project_name: projectName, 
        unblendedCost: 0, 
        blendedCost: 0, 
        amortizedCost: 0, 
        dailyCosts: {}, // <-- Track daily costs per project
        servicesMap: {} 
      };
    }
    projectSummaryMap[projectName].unblendedCost += unblended;
    projectSummaryMap[projectName].blendedCost += blended;
    projectSummaryMap[projectName].amortizedCost += amortized;

    if (!projectSummaryMap[projectName].servicesMap[service]) {
      projectSummaryMap[projectName].servicesMap[service] = { service, unblendedCost: 0 };
    }
    projectSummaryMap[projectName].servicesMap[service].unblendedCost += unblended;
  }
}

// Aggregate 30-Day Daily Totals & Record Project Daily Costs
const dailyTotalsMap = {};
const serviceWiseDaily = [];

for (const period of resolvedDaily) {
  const date = period.TimePeriod?.Start || '';
  if (!dailyTotalsMap[date]) {
    dailyTotalsMap[date] = { date, unblendedCost: 0, blendedCost: 0, amortizedCost: 0, unit: 'USD' };
  }
  for (const group of (period.Groups || [])) {
    const service = group.Keys?.[0] || 'Unknown';
    const rawTag = group.Keys?.[1] || '';
    let projectName = 'Untagged';
    if (rawTag && rawTag.includes('$')) {
      projectName = rawTag.split('$').slice(1).join('$').trim() || 'Untagged';
    } else if (rawTag) {
      projectName = rawTag.trim() || 'Untagged';
    }

    const unblended = parseFloat(group.Metrics?.UnblendedCost?.Amount || '0');
    const blended = parseFloat(group.Metrics?.BlendedCost?.Amount || '0');
    const amortized = parseFloat(group.Metrics?.AmortizedCost?.Amount || '0');

    // Account Daily Total
    dailyTotalsMap[date].unblendedCost += unblended;
    dailyTotalsMap[date].blendedCost += blended;
    dailyTotalsMap[date].amortizedCost += amortized;

    // Project Daily Timeline
    if (!projectSummaryMap[projectName]) {
      projectSummaryMap[projectName] = { 
        projectName, 
        project_name: projectName, 
        unblendedCost: 0, 
        blendedCost: 0, 
        amortizedCost: 0, 
        dailyCosts: {}, 
        servicesMap: {} 
      };
    }
    if (!projectSummaryMap[projectName].dailyCosts) {
      projectSummaryMap[projectName].dailyCosts = {};
    }
    projectSummaryMap[projectName].dailyCosts[date] = 
      (projectSummaryMap[projectName].dailyCosts[date] || 0) + unblended;

    if (unblended > 0) {
      serviceWiseDaily.push({ date, service, projectName, unblendedCost: Number(unblended.toFixed(4)), unit: 'USD' });
    }
  }
}

const sortedProjects = Object.values(projectSummaryMap)
  .map(p => ({
    projectName: p.projectName,
    project_name: p.project_name,
    unblendedCost: Number(p.unblendedCost.toFixed(2)),
    blendedCost: Number(p.blendedCost.toFixed(2)),
    amortizedCost: Number(p.amortizedCost.toFixed(2)),
    // Exact Daily Timeline per project directly from AWS:
    dailyTimeline: Object.entries(p.dailyCosts || {})
      .map(([d, cost]) => ({ date: d, unblendedCost: Number(cost.toFixed(2)) }))
      .sort((a, b) => a.date.localeCompare(b.date)),
    services: Object.values(p.servicesMap)
      .map(s => ({ service: s.service, unblendedCost: Number(s.unblendedCost.toFixed(2)) }))
      .sort((a, b) => b.unblendedCost - a.unblendedCost)
  }))
  .sort((a, b) => b.unblendedCost - a.unblendedCost);

const sortedServices = Object.values(serviceSummaryMap)
  .map(s => ({
    service: s.service,
    unblendedCost: Number(s.unblendedCost.toFixed(2)),
    blendedCost: Number(s.blendedCost.toFixed(2)),
    amortizedCost: Number(s.amortizedCost.toFixed(2))
  }))
  .sort((a, b) => b.unblendedCost - a.unblendedCost);

const dailyTotals = Object.values(dailyTotalsMap)
  .map(d => ({
    date: d.date,
    unblendedCost: Number(d.unblendedCost.toFixed(2)),
    blendedCost: Number(d.blendedCost.toFixed(2)),
    amortizedCost: Number(d.amortizedCost.toFixed(2))
  }))
  .sort((a, b) => a.date.localeCompare(b.date));

const documentToStore = {
  accountId,
  accountName: 'Production AWS Account',
  billingPeriod,
  timePeriod: { start: startDate, end: endDate },
  fetchedAt: new Date(),
  summary: {
    totalUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalBlendedCost: Number(totalBlended.toFixed(2)),
    totalNetUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalAmortizedCost: Number(totalAmortized.toFixed(2)),
    currency: 'USD'
  },
  serviceSummary: sortedServices,
  projectSummary: sortedProjects,
  dailyTotals,
  serviceWiseDaily,
  totalRecordsCount: serviceWiseDaily.length
};

return {
  json: {
    accountId,
    billingPeriod,
    syncDate: todayDate,
    syncedAt: new Date().toISOString(),
    totalUnblendedCost: Number(totalUnblended.toFixed(2)),
    totalAmortizedCost: Number(totalAmortized.toFixed(2)),
    serviceCount: sortedServices.length,
    projectCount: sortedProjects.length,
    daysCount: dailyTotals.length,
    document: documentToStore
  }
};
